// === Tab: halShader ===
const vert = `
precision mediump float;
attribute vec3 aPosition;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

uniform float time;

varying vec2 vTexCoord;
varying vec3 vNormal;
varying vec3 vPosition;

void main(void) {
  vec4 objSpacePosition = vec4(aPosition, 1.0);

  vec4 worldSpacePosition = uModelViewMatrix * objSpacePosition;
  gl_Position = uProjectionMatrix * worldSpacePosition;
  vTexCoord = aTexCoord;
  vPosition = worldSpacePosition.xyz;
  vNormal = uNormalMatrix * aNormal;
}
`

const frag = `
precision mediump float;
varying vec2 vTexCoord;
varying vec3 vNormal;
varying vec3 vPosition;
uniform mat3 uNormalMatrix;

const float PI = ${Math.PI.toFixed(10)};

mat3 transpose(mat3 inMatrix) {
	vec3 i0 = inMatrix[0];
	vec3 i1 = inMatrix[1];
	vec3 i2 = inMatrix[2];

	return mat3(
		 vec3(i0.x, i1.x, i2.x),
		 vec3(i0.y, i1.y, i2.y),
		 vec3(i0.z, i1.z, i2.z)
	 );
}

float fresnel(vec3 direction, vec3 normal, bool invert) {
  if (dot(direction, normal) > 0.0) return 0.0;
  vec3 halfDirection = normalize(normal + direction);
  float cosine = dot(halfDirection, direction);
  float product = max(cosine, 0.0);
  float factor = invert ? 1.0 - pow( product, 5.0 ) : pow( product, 5.0 );
  return factor;
}

// Noise functions
// https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
float rand(float n) {
	return fract(sin(n) * 43758.5453123);
}
float rand(vec2 n) { 
	return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}
float noise(float p) {
	float fl = floor(p);
	float fc = fract(p);
	return mix(rand(fl), rand(fl + 1.0), fc);
}
float noise(vec2 n) {
	const vec2 d = vec2(0.0, 1.0);
	vec2 b = floor(n);
	vec2 f = smoothstep(vec2(0.0), vec2(1.0), fract(n));
	return mix(mix(rand(b), rand(b + d.yx), f.x), mix(rand(b + d.xy), rand(b + d.yy), f.x), f.y);
}

const int NUM_SAMPLES = 12;

void main() {
  vec3 normal = normalize(vNormal);
	vec3 toSurface = normalize(vPosition);
	vec3 origDir = uNormalMatrix * reflect(toSurface, normal); //transpose(uNormalMatrix) * normal;
	float toCenter = dot(normal, vec3(0., 0., 1.));
	vec3 color = mix(
		vec3(0., 0., 0.),
		vec3(0.9, 0.05, 0.01),
		pow(toCenter, 4.)
	) + mix(
		vec3(0., 0., 0.),
		vec3(0.3, 0.7, 0.01),
		pow(toCenter, 200.)
	) + mix(
		vec3(0., 0., 0.),
		vec3(0.3, 0.7, 0.01),
		pow(toCenter, 400.)
	);

	vec2 coord = gl_FragCoord.xy;

	vec3 reflectionColor = vec3(0.,0.,0.);

	for (int i = 0; i < NUM_SAMPLES; i++) {
		float sampleOffset = float(i) * 123.456789;
		vec3 noiseOffset = vec3(
			fract(10. * noise(coord * 0.2) + sampleOffset) - 0.5,
			fract(10. * noise(coord * 0.2) + 10. + sampleOffset) - 0.5,
			fract(10. * noise(coord * 0.2) + 20. + sampleOffset) - 0.5
		);

		// reflected ray position on ceiling
		//
		// point is on plane when: dot(p - p_0, n) = 0
		// line: o + dir * t
		//
		// line intersection with plane:
		// dot((o + dir * t) - p_0, n) = 0
		// (o.x + dir.x*t - p_0.x) * n.x = -(o.y + dir.y*t - p_0.y) * n.y
		// n.x*o.x + n.x*dir.x*t - p_0.x*n.x = -n.y*o.y - n.y*dir.y*t + p_0.y*n.y
		// t*(n.x*dir.x + n.y*dir.y) = -n.x*o.x + p_0.x*n.x - n.y*o.y + p_0.y*n.y
		// t = (-n.x*o.x + p_0.x*n.x - n.y*o.y + p_0.y*n.y) / (n.x*dir.x + n.y*dir.y)
		// since n = (0, -1, 0):
		// t = (-n.y*o.y + p_0.y*n.y) / (n.y*dir.y)
		vec3 o = vPosition;
		vec3 dir = normalize(
			origDir +
				0.001 * noiseOffset * (0.05 + 1. - toCenter)
		);
		vec3 n = vec3(0., 1., 0.);
		vec3 p_0 = -n * 480.;
		// float t = (-n.y*o.y + p_0.y*n.y) / (n.y*dir.y);
		float t = (-n.x*o.x + p_0.x*n.x - n.y*o.y + p_0.y*n.y) / (n.x*dir.x + n.y*dir.y);
		vec3 p = o + dir * t;

		float rectW = 350.;
		float rectD = 300.;
		if (
			t > 0. &&
			mod(floor((p.x - rectW*.5)/rectW), 2.) == 0. &&
			mod(floor(p.z/rectD), 2.) == 0. &&
			abs(p.x - rectW*.5) < rectW * 8. &&
			abs(p.z) < rectD * 14.
		) {
			reflectionColor += vec3(1.,1.,1.) * 0.8;
		}
	}

	color += reflectionColor / float(NUM_SAMPLES);

	color += 2. * fresnel(toSurface, normal, false);

  gl_FragColor = vec4(color.rgb, 1.);
}
`

